92	
93	static const char *_get_rname(int type)
94	{
95	  int i = 0;
96	
97	  for (i = 0; i < sizeof(_rname_table) / sizeof(struct rname_code_s); i++)
98	    {
99	      if (_rname_table[i].type == type)
100	        {
101	          return _rname_table[i].name;
102	        }
103	    }
104	
105	  /* Not found in the table */
106	
107	  return "?????";
108	}
