184	/****************************************************************************
185	 * Name: _add_hi20
186	 *
187	 * Description:
188	 *   Add PCREL_HI20 relocation offset to the LUT. When a PCREL_LO12_I/_S is
189	 *   encountered, the corresponding PCREL_HI20 value can be found from it.
190	 *
191	 * Input Parameters:
192	 *   arch_data   - Where the PCREL_HI20 relocations are listed.
193	 *   hi20_rel    - The PCREL_HI20 relocation entry.
194	 *   hi20_offset - The corresponding offset value.
195	 *
196	 * Returned Value:
197	 *   None.
198	 *
199	 ****************************************************************************/
200	
201	static void _add_hi20(void *arch_data, uintptr_t hi20_rel,
202	                      uintptr_t hi20_offset)
203	{
204	  arch_elfdata_t *data = (arch_elfdata_t *)arch_data;
205	  int i;
206	
207	  /* Try to find a free slot from the list */
208	
209	  for (i = 0; i < ARCH_ELF_RELCNT; i++)
210	    {
211	      struct hi20_rels_s *hi20 = &data->hi20_rels[i];
212	
213	      if (hi20->hi20_rel == 0)
214	        {
215	          hi20->hi20_rel = hi20_rel;
216	          hi20->hi20_offset = hi20_offset;
217	          break;
218	        }
219	    }
220	}
221	
222	/****************************************************************************
223	 * Name: _find_hi20
224	 *
225	 * Description:
226	 *   Find PCREL_HI20 relocation offset from the LUT. When a PCREL_LO12_I/_S
227	 *   is encountered, the corresponding PCREL_HI20 value is needed to do the
228	 *   relocation.
229	 *
230	 * Input Parameters:
231	 *   arch_data   - Where the PCREL_HI20 relocations are listed.
232	 *   hi20_rel    - The PCREL_HI20 relocation entry.
233	 *
234	 * Returned Value:
235	 *   The corresponding hi20_offset value.
236	 *
237	 ****************************************************************************/
238	
239	static uintptr_t _find_hi20(void *arch_data, uintptr_t hi20_rel)
240	{
241	  arch_elfdata_t *data = (arch_elfdata_t *)arch_data;
242	  int i;
243	
244	  /* Try to find the hi20 value from the list */
245	
246	  for (i = 0; i < ARCH_ELF_RELCNT; i++)
247	    {
248	      struct hi20_rels_s *hi20 = &data->hi20_rels[i];
249	
250	      if (hi20->hi20_rel == hi20_rel)
251	        {
252	          /* Found it, we can clear the entry now */
253	
254	          hi20->hi20_rel = 0;
255	          return hi20->hi20_offset;
256	        }
257	    }
258	
259	  return 0;
260	}
