262	/****************************************************************************
263	 * Name: _valid_hi20_imm
264	 *
265	 * Description:
266	 *   Check that any XX_HI20 relocation has a valid upper 20-bit immediate.
267	 *   Note that this test is not necessary for RV32 targets, the problem is
268	 *   related to RV64 sign extension.
269	 *
270	 * Input Parameters:
271	 *   imm_hi - The upper immediate value.
272	 *
273	 * Returned Value:
274	 *   true if imm_hi is valid; false otherwise
275	 *
276	 ****************************************************************************/
277	
278	#ifdef CONFIG_ARCH_64BIT
279	static inline bool _valid_hi20_imm(long imm_hi)
280	{
281	  /* 32-bit sign extend imm_hi and compare with the original value */
282	
283	  long hi   = imm_hi & ((1 << 20) - 1);        /* 32-bit signed value */
284	  long sign = -((imm_hi >> 19) & 1);           /* 32-bit sign value */
285	  hi        = ((hi << 12) | sign << 32) >> 12; /* 32-bit sign extend */
286	
287	  /* If the values do not match, the immediate is invalid */
288	
289	  return imm_hi == hi;
290	}
291	#else
292	#  define _valid_hi20_imm(imm_hi) 1
293	#endif
