299	/****************************************************************************
300	 * Name: up_checkarch
301	 *
302	 * Description:
303	 *   Given the ELF header in 'hdr', verify that the ELF file is appropriate
304	 *   for the current, configured architecture.  Every architecture that uses
305	 *   the ELF loader must provide this function.
306	 *
307	 * Input Parameters:
308	 *   hdr - The ELF header read from the ELF file.
309	 *
310	 * Returned Value:
311	 *   True if the architecture supports this ELF file.
312	 *
313	 ****************************************************************************/
314	
315	bool up_checkarch(const Elf_Ehdr *ehdr)
316	{
317	  /* Make sure it's an RISCV executable */
318	
319	  if (ehdr->e_machine != EM_RISCV)
320	    {
321	      berr("ERROR: Not for RISCV: e_machine=%04x\n", ehdr->e_machine);
322	      return false;
323	    }
324	
325	  /* Make sure that current objects are supported */
326	
327	  if (ehdr->e_ident[EI_CLASS] != ELF_CLASS)
328	    {
329	      berr("ERROR: Need " ARCH_ELF_TYP_STR "-bit "
330	           "objects: e_ident[EI_CLASS]=%02x\n",
331	           ehdr->e_ident[EI_CLASS]);
332	      return false;
333	    }
334	
335	  /* Verify endian-ness */
336	
337	#ifdef CONFIG_ENDIAN_BIG
338	  if (ehdr->e_ident[EI_DATA] != ELFDATA2MSB)
339	#else
340	  if (ehdr->e_ident[EI_DATA] != ELFDATA2LSB)
341	#endif
342	    {
343	      berr("ERROR: Wrong endian-ness: e_ident[EI_DATA]=%02x\n",
344	           ehdr->e_ident[EI_DATA]);
345	      return false;
346	    }
347	
348	  /* Make sure the entry point address is properly aligned */
349	
350	  if ((ehdr->e_entry & 1) != 0)
351	    {
352	      berr("ERROR: Entry point is not properly aligned: %" PRIxPTR "\n",
353	           (uintptr_t)ehdr->e_entry);
354	    }
355	
356	  /* TODO:  Check ABI here. */
357	
358	  return true;
359	}
