361	/****************************************************************************
362	 * Name: up_relocate and up_relocateadd
363	 *
364	 * Description:
365	 *   Perform an architecture-specific ELF relocation.  Every architecture
366	 *   that uses the ELF loader must provide this function.
367	 *
368	 * Input Parameters:
369	 *   rel - The relocation type
370	 *   sym - The ELF symbol structure containing the fully resolved value.
371	 *         There are a few relocation types for a few architectures that do
372	 *         not require symbol information.  For those, this value will be
373	 *         NULL.  Implementations of these functions must be able to handle
374	 *         that case.
375	 *   addr - The address that requires the relocation.
376	 *
377	 * Returned Value:
378	 *   Zero (OK) if the relocation was successful.  Otherwise, a negated errno
379	 *   value indicating the cause of the relocation failure.
380	 *
381	 ****************************************************************************/
382	
383	int up_relocate(const Elf_Rel *rel, const Elf_Sym *sym, uintptr_t addr,
384	                void *arch_data)
385	{
386	  berr("Not implemented\n");
387	  return -ENOSYS;
388	}
389	
390	int up_relocateadd(const Elf_Rela *rel, const Elf_Sym *sym,
391	                   uintptr_t addr, void *arch_data)
392	{
393	  long offset;
394	  unsigned int relotype;
395	
396	  /* All relocations depend upon having valid symbol information */
397	
398	  relotype = ELF_R_TYPE(rel->r_info);
399	
400	  if (relotype == R_RISCV_RELAX)
401	    {
402	      /* NOTE: RELAX has no symbol, so just return */
403	
404	      binfo("%s at %08" PRIxPTR " [%08" PRIx32 "]\n",
405	            _get_rname(relotype),
406	            addr, _get_val((uint16_t *)addr));
407	
408	      return OK;
409	    }
410	
411	  if (sym == NULL && relotype != R_RISCV_NONE)
412	    {
413	      /* Raw UART debug */
414	      { volatile uint8_t *u = (volatile uint8_t *)0x04140000;
415	        const char *m = "BIND_NOSYM\n";
416	        while(*m){while((*(volatile uint32_t*)(0x04140014)&0x20)==0);*u=*m++;}
417	      }
418	      return -EINVAL;
419	    }
420	
421	  /* Do relocation based on relocation type */
422	
423	  switch (relotype)
424	    {
425	      case R_RISCV_32:
426	      case R_RISCV_64:
427	        {
428	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
429	                "to sym=%p st_value=%" PRIxPTR "\n",
430	                _get_rname(relotype),
431	                addr, _get_val((uint16_t *)addr),
432	                sym, (uintptr_t)sym->st_value);
433	
434	          _set_val((uint16_t *)addr,
435	                   (uint32_t)(sym->st_value + rel->r_addend));
436	        }
437	        break;
438	
439	      case R_RISCV_PCREL_LO12_I:
440	        {
441	          long imm_hi;
442	          long imm_lo;
443	
444	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
445	                "to sym=%p st_value=%" PRIxPTR "\n",
446	                _get_rname(relotype),
447	                addr, _get_val((uint16_t *)addr),
448	                sym, (uintptr_t)sym->st_value);
449	
450	          offset = _find_hi20(arch_data, sym->st_value);
451	
452	          /* Adjust imm for MV(ADDI) / JR (JALR) : I-type */
453	
454	          _calc_imm(offset, &imm_hi, &imm_lo);
455	
456	          _add_val((uint16_t *)addr, (int32_t)imm_lo << 20);
457	        }
458	        break;
459	
460	      case R_RISCV_PCREL_LO12_S:
461	        {
462	          uint32_t val;
463	          long imm_hi;
464	          long imm_lo;
465	
466	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
467	                "to sym=%p st_value=%" PRIxPTR "\n",
468	                _get_rname(relotype),
469	                addr, _get_val((uint16_t *)addr),
470	                sym, (uintptr_t)sym->st_value);
471	
472	          offset = _find_hi20(arch_data, sym->st_value);
473	
474	          /* Adjust imm for SW : S-type */
475	
476	          _calc_imm(offset, &imm_hi, &imm_lo);
477	
478	          val = (((int32_t)imm_lo >> 5) << 25) +
479	                (((int32_t)imm_lo & 0x1f) << 7);
480	
481	          binfo("imm_lo=%ld (%lx), val=%" PRIx32 "\n", imm_lo, imm_lo, val);
482	
483	          _add_val((uint16_t *)addr, val);
484	        }
485	        break;
486	
487	      case R_RISCV_PCREL_HI20:
488	        {
489	          uint32_t insn;
490	          long imm_hi;
491	          long imm_lo;
492	
493	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
494	                "to sym=%p st_value=%" PRIxPTR "\n",
495	                _get_rname(relotype),
496	                addr, _get_val((uint16_t *)addr),
497	                sym, (uintptr_t)sym->st_value);
498	
499	          offset = (long)sym->st_value + (long)rel->r_addend - (long)addr;
500	
501	          insn = _get_val((uint16_t *)addr);
502	          ASSERT(OPCODE_AUIPC == (insn & RVI_OPCODE_MASK));
503	
504	          _calc_imm(offset, &imm_hi, &imm_lo);
505	
506	          if (!_valid_hi20_imm(imm_hi))
507	            {
508	              berr("ERROR: %s at %08" PRIxPTR " bad:%08" PRIxPTR "\n",
509	                   _get_rname(relotype), addr, (uintptr_t)imm_hi << 12);
510	              { volatile uint8_t *u = (volatile uint8_t *)0x04140000;
511	                const char *m = "BIND_HI20BAD\n";
512	                while(*m){while((*(volatile uint32_t*)(0x04140014)&0x20)==0);*u=*m++;}
513	              }
514	              return -EINVAL;
515	            }
516	
517	          /* Adjust auipc (add upper immediate to pc) : 20bit */
518	
519	          _add_val((uint16_t *)addr, imm_hi << 12);
520	
521	          /* Add the hi20 value to the cache */
522	
523	          _add_hi20(arch_data, addr, offset);
524	        }
525	        break;
526	
527	      case R_RISCV_CALL:
528	      case R_RISCV_CALL_PLT:
529	        {
530	          long imm_hi;
531	          long imm_lo;
532	
533	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
534	                "to sym=%p st_value=%" PRIxPTR "\n",
535	                _get_rname(relotype),
536	                addr, _get_val((uint16_t *)addr),
537	                sym, (uintptr_t)sym->st_value);
538	
539	          offset = (long)sym->st_value + (long)rel->r_addend - (long)addr;
540	
541	          _calc_imm(offset, &imm_hi, &imm_lo);
542	
543	          if (!_valid_hi20_imm(imm_hi))
544	            {
545	              berr("ERROR: %s at %08" PRIxPTR " bad:%08" PRIxPTR "\n",
546	                   _get_rname(relotype), addr, (uintptr_t)imm_hi << 12);
547	              { volatile uint8_t *u = (volatile uint8_t *)0x04140000;
548	                const char *m = "BIND_CALLBAD\n";
549	                while(*m){while((*(volatile uint32_t*)(0x04140014)&0x20)==0);*u=*m++;}
550	              }
551	              return -EINVAL;
552	            }
553	
554	          /* Adjust auipc (add upper immediate to pc) : 20bit */
555	
556	          _add_val((uint16_t *)addr, imm_hi << 12);
557	
558	          /* Adjust imm for CALL (JALR) : I-type */
559	
560	          _add_val((uint16_t *)(addr + 4), (int32_t)imm_lo << 20);
561	        }
562	        break;
563	
564	      case R_RISCV_BRANCH:
565	        {
566	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
567	                "to sym=%p st_value=%" PRIxPTR "\n",
568	                _get_rname(relotype),
569	                addr, _get_val((uint16_t *)addr),
570	                sym, (uintptr_t)sym->st_value);
571	
572	          /* P.23 Conditinal Branches : B type (imm=12bit) */
573	
574	          offset = (long)sym->st_value + (long)rel->r_addend - (long)addr;
575	          uint32_t val = _get_val((uint16_t *)addr) & 0xfe000f80;
576	
577	          /* NOTE: we assume that a compiler adds an immediate value */
578	
579	          ASSERT(offset && val);
580	
581	          binfo("offset for Bx=%ld (0x%lx) (val=0x%08" PRIx32 ") "
582	                "already set!\n",
583	                offset, offset, val);
584	        }
585	        break;
586	
587	      case R_RISCV_JAL:
588	        {
589	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
590	                "to sym=%p st_value=%" PRIxPTR "\n",
591	                _get_rname(relotype),
592	                addr, _get_val((uint16_t *)addr),
593	                sym, (uintptr_t)sym->st_value);
594	
595	          /* P.21 Unconditinal Jumps : UJ type (imm=20bit) */
596	
597	          offset = (long)sym->st_value + (long)rel->r_addend - (long)addr;
598	          uint32_t val = _get_val((uint16_t *)addr) & 0xfffff000;
599	
600	          ASSERT(offset && val);
601	
602	          /* NOTE: we assume that a compiler adds an immediate value */
603	
604	          binfo("offset for JAL=%ld (0x%lx) (val=0x%08" PRIx32 ") "
605	                "already set!\n",
606	                offset, offset, val);
607	        }
608	        break;
609	
610	      case R_RISCV_HI20:
611	        {
612	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
613	                "to sym=%p st_value=%" PRIxPTR "\n",
614	                _get_rname(relotype),
615	                addr, _get_val((uint16_t *)addr),
616	                sym, (uintptr_t)sym->st_value);
617	
618	          /* P.19 LUI */
619	
620	          offset = (long)sym->st_value + (long)rel->r_addend;
621	          uint32_t insn = _get_val((uint16_t *)addr);
622	
623	          ASSERT(OPCODE_LUI == (insn & RVI_OPCODE_MASK));
624	
625	          long imm_hi;
626	          long imm_lo;
627	          _calc_imm(offset, &imm_hi, &imm_lo);
628	
629	          if (!_valid_hi20_imm(imm_hi))
630	            {
631	              berr("ERROR: %s at %08" PRIxPTR " bad:%08" PRIxPTR "\n",
632	                   _get_rname(relotype), addr, (uintptr_t)imm_hi << 12);
633	
634	              return -EINVAL;
635	            }
636	
637	          insn = (insn & 0x00000fff) | (imm_hi << 12);
638	
639	          _set_val((uint16_t *)addr, insn);
640	        }
641	        break;
642	
643	      case R_RISCV_LO12_I:
644	        {
645	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
646	                "to sym=%p st_value=%" PRIxPTR "\n",
647	                _get_rname(relotype),
648	                addr, _get_val((uint16_t *)addr),
649	                sym, (uintptr_t)sym->st_value);
650	
651	          /* ADDI, FLW, LD, ... : I-type */
652	
653	          offset = (long)sym->st_value + (long)rel->r_addend;
654	          uint32_t insn = _get_val((uint16_t *)addr);
655	
656	          long imm_hi;
657	          long imm_lo;
658	          _calc_imm(offset, &imm_hi, &imm_lo);
659	          insn = (insn & 0x000fffff) | (imm_lo << 20);
660	
661	          _set_val((uint16_t *)addr, insn);
662	        }
663	        break;
664	
665	      case R_RISCV_LO12_S:
666	        {
667	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
668	                "to sym=%p st_value=%" PRIxPTR "\n",
669	                _get_rname(relotype),
670	                addr, _get_val((uint16_t *)addr),
671	                sym, (uintptr_t)sym->st_value);
672	
673	          /* SW : S-type.
674	           * not merge with R_RISCV_HI20 since the compiler
675	           * may not generates these two instructions continuously.
676	           */
677	
678	          offset = (long)sym->st_value + (long)rel->r_addend;
679	
680	          long imm_hi;
681	          long imm_lo;
682	          _calc_imm(offset, &imm_hi, &imm_lo);
683	
684	          uint32_t val =
685	              (((int32_t)imm_lo >> 5) << 25) +
686	              (((int32_t)imm_lo & 0x1f) << 7);
687	
688	          binfo("imm_lo=%ld (%lx), val=%" PRIx32 "\n", imm_lo, imm_lo, val);
689	
690	          _add_val((uint16_t *)addr, val);
691	        }
692	        break;
693	
694	      case R_RISCV_RVC_JUMP:
695	        {
696	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
697	                "to sym=%p st_value=%" PRIxPTR "\n",
698	                _get_rname(relotype),
699	                addr, _get_val((uint16_t *)addr),
700	                sym, (uintptr_t)sym->st_value);
701	
702	          /* P.111 Table 16.6 : Instruction listings for RVC */
703	
704	          offset = (long)sym->st_value + (long)rel->r_addend - (long)addr;
705	          ASSERT(-2048 <= offset && offset <= 2047);
706	
707	          uint16_t val = (*(uint16_t *)addr) & 0x1ffc;
708	
709	          binfo("offset for C.J=%ld (0x%lx) (val=0x%04x) already set!\n",
710	                offset, offset, val);
711	        }
712	        break;
713	
714	      case R_RISCV_RVC_BRANCH:
715	        {
716	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
717	                "to sym=%p st_value=%" PRIxPTR "\n",
718	                _get_rname(relotype),
719	                addr, _get_val((uint16_t *)addr),
720	                sym, (uintptr_t)sym->st_value);
721	
722	          /* P.111 Table 16.6 : Instruction listings for RVC */
723	
724	          offset = (long)sym->st_value + (long)rel->r_addend - (long)addr;
725	          ASSERT(-256 <= offset && offset <= 255);
726	
727	          uint16_t val = (*(uint16_t *)addr) & 0x1c7c;
728	
729	          /* NOTE: we assume that a compiler adds an immediate value */
730	
731	          ASSERT(offset && val);
732	
733	          binfo("offset for C.Bx=%ld (0x%lx) (val=0x%04x) already set!\n",
734	                offset, offset, val);
735	        }
736	        break;
737	      case R_RISCV_32_PCREL:
738	        {
739	          /* P.29 https://github.com/riscv-non-isa/riscv-elf-psabi-doc */
740	
741	          binfo("%s at %08" PRIxPTR " [%08" PRIx32 "] "
742	                "to sym=%p st_value=%" PRIxPTR "\n",
743	                _get_rname(relotype),
744	                addr, _get_val((uint16_t *)addr),
745	                sym, (uintptr_t)sym->st_value);
746	
747	          addr = (long)sym->st_value + (long)rel->r_addend - (long)addr;
748	        }
749	        break;
750	      case R_RISCV_ADD32:
751	        {
752	          *(uint32_t *)addr += (uint32_t)(sym->st_value + rel->r_addend);
753	        }
754	        break;
755	      case R_RISCV_ADD64:
756	        {
757	          *(uint64_t *)addr += (uint64_t)(sym->st_value + rel->r_addend);
758	        }
759	        break;
760	      case R_RISCV_SUB16:
761	        {
762	          *(uint16_t *)addr -= (uint16_t)(sym->st_value + rel->r_addend);
763	        }
764	        break;
765	      case R_RISCV_SUB32:
766	        {
767	          *(uint32_t *)addr -= (uint32_t)(sym->st_value + rel->r_addend);
768	        }
769	        break;
770	      case R_RISCV_SUB64:
771	        {
772	          *(uint64_t *)addr -= (uint64_t)(sym->st_value + rel->r_addend);
773	        }
774	        break;
775	      case R_RISCV_SET16:
776	        {
777	          *(uint16_t *)addr = (uint16_t)(sym->st_value + rel->r_addend);
778	        }
779	        break;
780	      default:
781	        berr("ERROR: Unsupported relocation: %" PRIu32 "\n",
782	             (uint32_t)ELF_R_TYPE(rel->r_info));
783	        { volatile uint8_t *u = (volatile uint8_t *)0x04140000;
784	          const char *m = "BIND_BADREL\n";
785	          while(*m){while((*(volatile uint32_t*)(0x04140014)&0x20)==0);*u=*m++;}
786	        }
787	        PANIC();
788	        return -EINVAL;
789	    }
790	
791	  return OK;
792	}
