85	/****************************************************************************
86	 * Name: elf_loadbinary
87	 *
88	 * Description:
89	 *   Verify that the file is an ELF binary and, if so, load the ELF
90	 *   binary into memory
91	 *
92	 ****************************************************************************/
93	
94	static int elf_loadbinary(FAR struct binary_s *binp,
95	                          FAR const char *filename,
96	                          FAR const struct symtab_s *exports,
97	                          int nexports)
98	{
99	  struct mod_loadinfo_s loadinfo;
100	  Elf_Sym sym;
101	  int ret;
102	
103	  binfo("Loading file: %s\n", filename);
104	
105	  /* Initialize the ELF library to load the program binary. */
106	
107	  ret = libelf_initialize(filename, &loadinfo);
108	  libelf_dumploadinfo(&loadinfo);
109	  if (ret != 0)
110	    {
111	      { volatile uint8_t *u = (volatile uint8_t *)0x04140000;
112	        const char *m = "ELF_INIT_FAIL\n";
113	        while(*m){while((*(volatile uint32_t*)(0x04140014)&0x20)==0);*u=*m++;} }
114	      goto errout_with_init;
115	    }
116	
117	  /* Load the program binary */
118	
119	  ret = libelf_load_with_addrenv(&loadinfo, false);
120	  libelf_dumploadinfo(&loadinfo);
121	  if (ret != 0)
122	    {
123	      berr("Failed to load ELF program binary: %d\n", ret);
124	      { volatile uint8_t *u = (volatile uint8_t *)0x04140000;
125	        const char *m = "ELF_LOAD_FAIL\n";
126	        while(*m){while((*(volatile uint32_t*)(0x04140014)&0x20)==0);*u=*m++;} }
127	      goto errout_with_init;
128	    }
129	
130	  /* Bind the program to the exported symbol table */
131	
132	  if (loadinfo.ehdr.e_type == ET_REL
133	#ifdef CONFIG_LIBC_ELF_GOT
134	      || loadinfo.gotindex >= 0
135	#endif
136	     )
137	    {
138	      ret = libelf_bind(&binp->mod, &loadinfo, exports, nexports);
139	      if (ret != 0)
140	        {
141	          berr("Failed to bind symbols program binary: %d\n", ret);
142	          { volatile uint8_t *u = (volatile uint8_t *)0x04140000;
143	            const char *m = "ELF_BIND_FAIL\n";
144	            while(*m){while((*(volatile uint32_t*)(0x04140014)&0x20)==0);*u=*m++;} }
145	          goto errout_with_load;
146	        }
147	
148	      binp->entrypt = (main_t)(loadinfo.textalloc + loadinfo.ehdr.e_entry);
149	    }
150	  else if (loadinfo.ehdr.e_type == ET_EXEC)
151	    {
152	      if (nexports > 0)
153	        {
154	          berr("Cannot bind exported symbols to a "
155	               "fully linked executable\n");
156	          ret = -ENOEXEC;
157	          goto errout_with_load;
158	        }
159	
160	      /* The entrypoint for a fully linked executable can be found directly */
161	
162	      binp->entrypt = (main_t)(loadinfo.ehdr.e_entry);
163	    }
164	
165	  else
166	    {
167	      berr("Unexpected elf type %d\n", loadinfo.ehdr.e_type);
168	      ret = -ENOEXEC;
169	      goto errout_with_load;
170	    }
171	
172	  /* Return the load information */
173	
174	  ret = libelf_findsymbol(&loadinfo, "nx_stacksize", &sym);
175	  if (ret == 0)
176	    {
177	      binp->stacksize = sym.st_value;
178	    }
179	  else
180	    {
181	      binp->stacksize = CONFIG_ELF_STACKSIZE;
182	    }
183	
184	  ret = libelf_findsymbol(&loadinfo, "nx_priority", &sym);
185	  if (ret == 0)
186	    {
187	      binp->priority = sym.st_value;
188	    }
189	  else
190	    {
191	      binp->priority = SCHED_PRIORITY_DEFAULT;
192	    }
193	
194	#ifdef CONFIG_SCHED_USER_IDENTITY
195	  ret = libelf_findsymbol(&loadinfo, "nx_uid", &sym);
196	  if (ret == 0)
197	    {
198	      binp->uid = sym.st_value;
199	    }
200	  else
201	    {
202	      binp->uid = 0;
203	    }
204	
205	  ret = libelf_findsymbol(&loadinfo, "nx_gid", &sym);
206	  if (ret == 0)
207	    {
208	      binp->gid = sym.st_value;
209	    }
210	  else
211	    {
212	      binp->gid = 0;
213	    }
214	
215	  ret = libelf_findsymbol(&loadinfo, "nx_mode", &sym);
216	  if (ret == 0)
217	    {
218	      binp->mode = sym.st_value;
219	    }
220	  else
221	    {
222	      binp->mode = 0;
223	    }
224	#endif
225	
226	#ifdef CONFIG_MM_TASK_HEAP
227	  ret = libelf_findsymbol(&loadinfo, "nx_heapsize", &sym);
228	  if (ret == 0)
229	    {
230	      binp->heapsize = sym.st_value;
231	    }
232	  else
233	    {
234	      binp->priority = CONFIG_MM_TASK_HEAP_DEFAULT_SIZE;
235	    }
236	#endif
237	
238	  /* Add the ELF allocation to the alloc[] only if there is no address
239	   * environment.  If there is an address environment, it will automatically
240	   * be freed when the function exits
241	   *
242	   * REVISIT:  If the module is loaded then unloaded, wouldn't this cause
243	   * a memory leak?
244	   */
245	
246	#ifdef CONFIG_ARCH_ADDRENV
247	  /* Save the address environment in the binfmt structure.  This will be
248	   * needed when the module is executed.
249	   */
250	
251	  binp->addrenv = loadinfo.addrenv;
252	
253	#else
254	#  ifdef CONFIG_ARCH_USE_SEPARATED_SECTION
255	  if (loadinfo.ehdr.e_type == ET_REL)
256	    {
257	      binp->mod.sectalloc = (FAR void *)loadinfo.sectalloc;
258	      binp->mod.nsect     = loadinfo.ehdr.e_shnum;
259	    }
260	#  endif
261	
262	  binp->mod.textalloc = (FAR void *)loadinfo.textalloc;
263	  binp->mod.dataalloc = (FAR void *)loadinfo.datastart;
264	#  ifdef CONFIG_BINFMT_CONSTRUCTORS
265	  binp->mod.initarr = loadinfo.initarr;
266	  binp->mod.finiarr = loadinfo.finiarr;
267	#  endif
268	#endif
269	
270	#ifdef CONFIG_BINFMT_CONSTRUCTORS
271	  /* Save information about constructors and destructors. */
272	
273	  binp->mod.initarr = loadinfo.initarr;
274	  binp->mod.ninit   = loadinfo.ninit;
275	
276	  binp->mod.finiarr = loadinfo.finiarr;
277	  binp->mod.nfini   = loadinfo.nfini;
278	#endif
279	
280	#ifdef CONFIG_SCHED_USER_IDENTITY
281	  /* Save IDs and mode from file system */
282	
283	  binp->uid  = loadinfo.fileuid;
284	  binp->gid  = loadinfo.filegid;
285	  binp->mode = loadinfo.filemode;
286	#endif
287	
288	  libelf_dumpentrypt(&loadinfo);
289	#if defined(CONFIG_PIC) && defined(CONFIG_LIBC_ELF_GOT)
290	  if (loadinfo.gotindex >= 0)
291	    {
292	      FAR struct dspace_s *dspaces = kmm_zalloc(sizeof(struct dspace_s));
293	
294	      if (dspaces == NULL)
295	        {
296	          ret = -ENOMEM;
297	          goto errout_with_load;
298	        }
299	
300	      dspaces->region = (FAR void *)loadinfo.shdr[loadinfo.gotindex].sh_addr;
301	      dspaces->crefs = 1;
302	      binp->picbase = (FAR void *)dspaces;
303	    }
304	#endif
305	
306	#ifdef HAVE_LIBC_ELF_NAMES
307	  /* Save the filename in the registry entry */
308	
309	  strlcpy(binp->mod.modname, strrchr(filename, '/') == NULL ?
310	          filename: strrchr(filename, '/') + 1,
311	          sizeof(binp->mod.modname));
312	#endif
313	
314	  libelf_uninitialize(&loadinfo);
315	  return OK;
316	
317	errout_with_load:
318	  libelf_unload(&loadinfo);
319	errout_with_init:
320	  libelf_uninitialize(&loadinfo);
321	  return ret;
322	}
323	
324	/****************************************************************************
325	 * Name: elf_unloadbinary
326	 *
327	 * Description:
328	 *   Unload the ELF binary that was loaded into memory by elf_loadbinary.
329	 *
330	 ****************************************************************************/
331	
332	static int elf_unloadbinary(FAR struct binary_s *binp)
333	{
334	  binfo("Unloading %p\n", binp);
335	  libelf_uninit(&binp->mod);
336	
337	  return OK;
338	}
