344	/****************************************************************************
345	 * Name: elf_initialize
346	 *
347	 * Description:
348	 *   In order to use the ELF binary format, this function must be called
349	 *   during system initialization to register the ELF binary format.
350	 *
351	 * Returned Value:
352	 *   This is a NuttX internal function so it follows the convention that
353	 *   0 (OK) is returned on success and a negated errno is returned on
354	 *   failure.
355	 *
356	 ****************************************************************************/
357	
358	int elf_initialize(void)
359	{
360	  int ret;
361	
362	  /* Register ourselves as a binfmt loader */
363	
364	  binfo("Registering ELF\n");
365	
366	  ret = register_binfmt(&g_elfbinfmt);
367	  if (ret != 0)
368	    {
369	      berr("Failed to register binfmt: %d\n", ret);
370	    }
371	
372	  return ret;
373	}
