135	 *
136	 * Description:
137	 *   Read the (ELF_Rela structure * buffer count) into memory.
138	 *
139	 ****************************************************************************/
140	
141	static inline int libelf_readrelas(FAR struct mod_loadinfo_s *loadinfo,
142	                                   FAR const Elf_Shdr *relsec,
143	                                   int index, FAR Elf_Rela *relas,
144	                                   int count)
145	{
146	  off_t offset;
147	  int size;
148	
149	  /* Verify that the symbol table index lies within symbol table */
150	
151	  if (index < 0 || index > (relsec->sh_size / sizeof(Elf_Rela)))
152	    {
153	      berr("ERROR: Bad relocation symbol index: %d\n", index);
154	      return -EINVAL;
155	    }
156	
157	  /* Get the file offset to the symbol table entry */
158	
159	  offset = sizeof(Elf_Rela) * index;
160	  size   = sizeof(Elf_Rela) * count;
161	  if (offset + size > relsec->sh_size)
162	    {
163	      size = relsec->sh_size - offset;
164	    }
165	
166	  /* And, finally, read the symbol table entry into memory */
167	
168	  return libelf_read(loadinfo, (FAR uint8_t *)relas, size,
169	                     relsec->sh_offset + offset);
170	}
