635	/****************************************************************************
636	 * Name: libelf_relocatedyn
637	 *
638	 * Description:
639	 *   Perform all relocations associated with a dynamic section.
640	 *
641	 * Returned Value:
642	 *   0 (OK) is returned on success and a negated errno is returned on
643	 *   failure.
644	 *
645	 ****************************************************************************/
646	
647	static int libelf_relocatedyn(FAR struct module_s *modp,
648	                              FAR struct mod_loadinfo_s *loadinfo,
649	                              int relidx)
650	{
651	  FAR Elf_Shdr *shdr = &loadinfo->shdr[relidx];
652	  FAR Elf_Shdr *symhdr;
653	  FAR Elf_Dyn  *dyn = NULL;
654	  FAR Elf_Rel  *rels = NULL;
655	  FAR Elf_Rel  *rel;
656	  FAR Elf_Rela *relas = NULL;
657	  FAR Elf_Rela *rela;
658	  FAR Elf_Sym  *sym = NULL;
659	  uintptr_t     addr;
660	  int           ret;
661	  int           i;
662	  int           idx_rel;
663	  int           idx_sym;
664	
665	  /* Define potential architecture specific elf data container */
666	
667	  ARCH_ELFDATA_DEF;
668	
669	  dyn = lib_malloc(shdr->sh_size);
670	  if (dyn == NULL)
671	    {
672	      berr("Failed to allocate memory for elf dynamic section\n");
673	      return -ENOMEM;
674	    }
675	
676	  ret = libelf_read(loadinfo, (FAR uint8_t *)dyn, shdr->sh_size,
677	                    shdr->sh_offset);
678	  if (ret < 0)
679	    {
680	      berr("Failed to read dynamic section header");
681	      lib_free(dyn);
682	      return ret;
683	    }
684	
685	  /* Assume DT_RELA to get maximum size required */
686	
687	  rels = lib_zalloc(CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT *
688	                    sizeof(Elf_Rela));
689	  if (!rels)
690	    {
691	      berr("Failed to allocate memory for elf relocation rels\n");
692	      lib_free(dyn);
693	      return -ENOMEM;
694	    }
695	
696	  memset((FAR void *)&reldata, 0, sizeof(reldata));
697	  relas = (FAR Elf_Rela *)rels;
698	
699	  for (i = 0; dyn[i].d_tag != DT_NULL; i++)
700	    {
701	      switch (dyn[i].d_tag)
702	        {
703	          case DT_REL:
704	            reldata.reloff[I_REL] = dyn[i].d_un.d_val;
705	            break;
706	          case DT_RELSZ:
707	            reldata.relsz[I_REL] = dyn[i].d_un.d_val;
708	            break;
709	          case DT_RELENT:
710	            reldata.relentsz[I_REL] = dyn[i].d_un.d_val;
711	            break;
712	          case DT_SYMTAB:
713	            reldata.symoff = dyn[i].d_un.d_val;
714	            break;
715	          case DT_STRTAB:
716	            reldata.stroff = dyn[i].d_un.d_val;
717	            break;
718	          case DT_JMPREL:
719	            reldata.reloff[I_PLT] = dyn[i].d_un.d_val;
720	            break;
721	          case DT_PLTRELSZ:
722	            reldata.relsz[I_PLT] = dyn[i].d_un.d_val;
723	            break;
724	          case DT_PLTREL:
725	            if (dyn[i].d_un.d_val == DT_REL)
726	              {
727	                reldata.relentsz[I_PLT] = sizeof(Elf_Rel);
728	                reldata.relrela[I_PLT] = 0;
729	              }
730	            else
731	              {
732	                reldata.relentsz[I_PLT] = sizeof(Elf_Rela);
733	                reldata.relrela[I_PLT] = 1;
734	              }
735	            break;
736	        }
737	    }
738	
739	  symhdr = &loadinfo->shdr[loadinfo->dsymtabidx];
740	  sym = lib_malloc(symhdr->sh_size);
741	  if (!sym)
742	    {
743	      berr("Error obtaining storage for dynamic symbol table");
744	      lib_free(rels);
745	      lib_free(dyn);
746	      return -ENOMEM;
747	    }
748	
749	  ret = libelf_read(loadinfo, (FAR uint8_t *)sym, symhdr->sh_size,
750	                    symhdr->sh_offset);
751	  if (ret < 0)
752	    {
753	      berr("Error reading dynamic symbol table - %d", ret);
754	      lib_free(sym);
755	      lib_free(rels);
756	      lib_free(dyn);
757	      return ret;
758	    }
759	
760	  reldata.lsymtab = reldata.stroff - reldata.symoff;
761	
762	  for (idx_rel = 0; idx_rel < N_RELS; idx_rel++)
763	    {
764	      int lrelent;
765	
766	      if ((reldata.relsz[idx_rel] == 0) || (reldata.reloff[idx_rel] == 0))
767	        {
768	          continue;
769	        }
770	
771	      /* Examine each relocation in the .rel.* section. */
772	
773	      ret = OK;
774	      lrelent = reldata.relsz[idx_rel] / reldata.relentsz[idx_rel];
775	
776	      for (i = 0; i < lrelent; i++)
777	        {
778	          /* Process each relocation entry
779	           * - we cheat by using the fact the 1st two fields of Elf_Rel
780	           *   and Elf_Rela are identical so can do things based on the
781	           *   former until it's important
782	           */
783	
784	          if (reldata.relrela[idx_rel] == 0)
785	            {
786	              rel = &rels[i % CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT];
787	              rela = (Elf_Rela *)rel;  /* Just to keep the compiler happy */
788	            }
789	          else
790	            {
791	              rela = &relas[i % CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT];
792	              rel = (Elf_Rel *)rela;
793	            }
794	
795	          if (!(i % CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT))
796	            {
797	              size_t relsize = (sizeof(Elf_Rela) *
798	                               CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT);
799	
800	              if (reldata.relsz[idx_rel] < relsize)
801	                {
802	                  relsize = reldata.relsz[idx_rel];
803	                }
804	
805	              ret = libelf_read(loadinfo, (FAR uint8_t *)rels,
806	                                relsize,
807	                                reldata.reloff[idx_rel] +
808	                                i * sizeof(Elf_Rel));
809	
810	              if (ret < 0)
811	                {
812	                  berr("ERROR: Section %d reloc %d:"
813	                       "Failed to read relocation entry: %d\n",
814	                       relidx, i, ret);
815	                  break;
816	                }
817	            }
818	
819	          /* Now perform the architecture-specific relocation */
820	
821	          if ((idx_sym = ELF_R_SYM(rel->r_info)) != 0)
822	            {
823	              /* We have an external reference */
824	
825	              if (sym[idx_sym].st_shndx == SHN_UNDEF)
826	                {
827	                    FAR void *ep;
828	
829	                    ep = libelf_findglobal(modp, loadinfo, symhdr,
830	                                           &sym[idx_sym]);
831	                    if ((ep == NULL) && (ELF_ST_BIND(sym[idx_sym].st_info)
832	                        != STB_WEAK))
833	                      {
834	                        berr("ERROR: Unable to resolve addr of ext ref %s\n",
835	                             loadinfo->iobuffer);
836	                        ret = -EINVAL;
837	                        lib_free(sym);
838	                        lib_free(rels);
839	                        lib_free(dyn);
840	                        return ret;
841	                      }
842	
843	                    addr = rel->r_offset + loadinfo->textalloc;
844	
845	                    if (reldata.relrela[idx_rel] == 1)
846	                      {
847	                        addr += rela->r_addend;
848	                      }
849	
850	                    *(FAR uintptr_t *)addr = (uintptr_t)ep;
851	                }
852	            }
853	          else
854	            {
855	              Elf_Sym dynsym =
856	                {
857	                  0
858	                };
859	
860	              addr = rel->r_offset - loadinfo->datasec + loadinfo->datastart;
861	
862	              if (reldata.relrela[idx_rel] == 1)
863	                {
864	                  addr += rela->r_addend;
865	                }
866	
867	              if ((*(FAR uint32_t *)addr) < loadinfo->datasec)
868	                {
869	                  dynsym.st_value = *(FAR uint32_t *)addr +
870	                                    loadinfo->textalloc;
871	                }
872	              else
873	                {
874	                  dynsym.st_value = *(FAR uint32_t *)addr -
875	                                    loadinfo->datasec + loadinfo->datastart;
876	                }
877	
878	              ret = up_relocate(rel, &dynsym, addr, ARCH_ELFDATA_PARM);
879	            }
880	
881	          if (ret < 0)
882	            {
883	              berr("ERROR: Section %d reloc %d: Relocation failed: %d\n",
884	                   relidx, i, ret);
885	              lib_free(sym);
886	              lib_free(rels);
887	              lib_free(dyn);
888	              return ret;
889	            }
890	        }
891	    }
892	
893	  lib_free(sym);
894	  lib_free(rels);
895	  lib_free(dyn);
896	
897	  return ret;
898	}
