901	 * Public Functions
902	 ****************************************************************************/
903	
904	/****************************************************************************
905	 * Name: libelf_bind
906	 *
907	 * Description:
908	 *   Bind the imported symbol names in the loaded module described by
909	 *   'loadinfo' using the exported symbol values provided by
910	 *   libelf_setsymtab().
911	 *
912	 * Input Parameters:
913	 *   modp     - Module state information
914	 *   loadinfo - Load state information
915	 *   exports  - The table of exported symbols
916	 *   nexports - The number of symbols in the exports table
917	 *
918	 * Returned Value:
919	 *   0 (OK) is returned on success and a negated errno is returned on
920	 *   failure.
921	 *
922	 ****************************************************************************/
923	
924	int libelf_bind(FAR struct module_s *modp,
925	                FAR struct mod_loadinfo_s *loadinfo,
926	                FAR const struct symtab_s *exports, int nexports)
927	{
928	  int ret;
929	  int i;
930	
931	#ifdef CONFIG_ARCH_ADDRENV
932	  /* If CONFIG_ARCH_ADDRENV=y, then the loaded ELF lies in a virtual address
933	   * space that may not be in place now.  libelf_addrenv_select() will
934	   * temporarily instantiate that address space.
935	   */
936	
937	  if (loadinfo->addrenv != NULL)
938	    {
939	      ret = libelf_addrenv_select(loadinfo);
940	      if (ret < 0)
941	        {
942	          berr("ERROR: libelf_addrenv_select() failed: %d\n", ret);
943	          { volatile uint8_t *u = (volatile uint8_t *)0x04140000;
944	            const char *m = "ELF_ADRENV_FAIL\n";
945	            while(*m){while((*(volatile uint32_t*)(0x04140014)&0x20)==0);*u=*m++;}
946	          }
947	          return ret;
948	        }
949	    }
950	#endif
951	
952	  /* Find the symbol and string tables */
953	
954	  ret = libelf_findsymtab(loadinfo);
955	  if (ret < 0)
956	    {
957	      { volatile uint8_t *u = (volatile uint8_t *)0x04140000;
958	        const char *m = "ELF_SYMTAB_FAIL\n";
959	        while(*m){while((*(volatile uint32_t*)(0x04140014)&0x20)==0);*u=*m++;}
960	      }
961	      return ret;
962	    }
963	
964	  /* Process relocations in every allocated section */
965	
966	  for (i = 1; i < loadinfo->ehdr.e_shnum; i++)
967	    {
968	      /* Get the index to the relocation section */
969	
970	      int infosec = loadinfo->shdr[i].sh_info;
971	      if (infosec >= loadinfo->ehdr.e_shnum)
972	        {
973	          continue;
974	        }
975	
976	      if (loadinfo->ehdr.e_type == ET_DYN)
977	        {
978	          modp->dynamic = 1;
979	          switch (loadinfo->shdr[i].sh_type)
980	            {
981	              case SHT_DYNAMIC:
982	                ret = libelf_relocatedyn(modp, loadinfo, i);
983	                break;
984	              case SHT_DYNSYM:
985	                loadinfo->dsymtabidx = i;
986	                break;
987	              case SHT_INIT_ARRAY:
988	                loadinfo->initarr = loadinfo->shdr[i].sh_addr -
989	                                    loadinfo->datasec +
990	                                    loadinfo->datastart;
991	                loadinfo->ninit = loadinfo->shdr[i].sh_size /
992	                                  sizeof(uintptr_t);
993	                break;
994	              case SHT_FINI_ARRAY:
995	                loadinfo->finiarr = loadinfo->shdr[i].sh_addr -
996	                                    loadinfo->datasec +
997	                                    loadinfo->datastart;
998	                loadinfo->nfini = loadinfo->shdr[i].sh_size /
999	                                  sizeof(uintptr_t);
1000	                break;
1001	              case SHT_PREINIT_ARRAY:
1002	                loadinfo->preiarr = loadinfo->shdr[i].sh_addr -
1003	                                    loadinfo->datasec +
1004	                                    loadinfo->datastart;
1005	                loadinfo->nprei = loadinfo->shdr[i].sh_size /
1006	                                  sizeof(uintptr_t);
1007	                break;
1008	            }
1009	
1010	          if (ret < 0)
1011	            {
1012	              return ret;
1013	            }
1014	        }
1015	      else
1016	        {
1017	          modp->dynamic = 0;
1018	
1019	          /* Make sure that the section is allocated.  We can't
1020	           * relocate sections that were not loaded into memory.
1021	           */
1022	
1023	          if ((loadinfo->shdr[i].sh_flags & SHF_ALLOC) == 0 &&
1024	              (loadinfo->shdr[i].sh_flags & SHF_INFO_LINK) == 0)
1025	            {
1026	              continue;
1027	            }
1028	
1029	          /* Process the relocations by type */
1030	
1031	          switch (loadinfo->shdr[i].sh_type)
1032	            {
1033	              case SHT_REL:
1034	                if ((loadinfo->shdr[infosec].sh_flags & SHF_ALLOC) == 0)
1035	                  {
1036	                    continue;
1037	                  }
1038	
1039	                ret = libelf_relocate(modp, loadinfo, i, exports, nexports);
1040	                break;
1041	              case SHT_RELA:
1042	                if ((loadinfo->shdr[infosec].sh_flags & SHF_ALLOC) == 0)
1043	                  {
1044	                    continue;
1045	                  }
1046	
1047	                ret = libelf_relocateadd(modp, loadinfo, i, exports,
1048	                                         nexports);
1049	                break;
1050	              case SHT_INIT_ARRAY:
1051	                loadinfo->initarr = loadinfo->shdr[i].sh_addr;
1052	                loadinfo->ninit = loadinfo->shdr[i].sh_size /
1053	                                  sizeof(uintptr_t);
1054	                break;
1055	              case SHT_FINI_ARRAY:
1056	                loadinfo->finiarr = loadinfo->shdr[i].sh_addr;
1057	                loadinfo->nfini = loadinfo->shdr[i].sh_size /
1058	                                  sizeof(uintptr_t);
1059	                break;
1060	            }
1061	        }
1062	
1063	      if (ret < 0)
1064	        {
1065	          return ret;
1066	        }
1067	    }
1068	
1069	#ifdef CONFIG_LIBC_ELF_GOT
1070	  modp->xipbase = loadinfo->xipbase;
1071	#endif
1072	
1073	  /* Ensure that the I and D caches are coherent before starting the newly
1074	   * loaded module by cleaning the D cache (i.e., flushing the D cache
1075	   * contents to memory and invalidating the I cache).
1076	   */
1077	
1078	  if (loadinfo->textsize > 0)
1079	    {
1080	      up_coherent_dcache(loadinfo->textalloc, loadinfo->textsize);
1081	    }
1082	
1083	  if (loadinfo->datasize > 0)
1084	    {
1085	      up_coherent_dcache(loadinfo->datastart, loadinfo->datasize);
1086	    }
1087	
1088	#ifdef CONFIG_ARCH_USE_SEPARATED_SECTION
1089	  for (i = 0; loadinfo->ehdr.e_type == ET_REL && i < loadinfo->ehdr.e_shnum;
1090	       i++)
1091	    {
1092	      if (loadinfo->sectalloc[i] == 0)
1093	        {
1094	          continue;
1095	        }
1096	
1097	      up_coherent_dcache(loadinfo->sectalloc[i], loadinfo->shdr[i].sh_size);
1098	    }
1099	#endif
1100	
1101	#ifdef CONFIG_ARCH_ADDRENV
1102	  if (loadinfo->addrenv != NULL)
1103	    {
1104	      int status = libelf_addrenv_restore(loadinfo);
1105	      if (status < 0)
1106	        {
1107	          berr("ERROR: libelf_addrenv_restore() failed: %d\n", status);
1108	          if (ret == OK)
1109	            {
1110	              ret = status;
1111	            }
1112	        }
1113	    }
1114	#endif
1115	
1116	  return ret;
1117	}
