707	/****************************************************************************
708	 * Name: libelf_load_with_addrenv
709	 *
710	 * Description:
711	 *   Loads the binary into memory, use the address environment to load the
712	 *   binary.
713	 *
714	 * Returned Value:
715	 *   0 (OK) is returned on success and a negated errno is returned on
716	 *   failure.
717	 *
718	 ****************************************************************************/
719	
720	#ifdef CONFIG_ARCH_ADDRENV
721	int libelf_load_with_addrenv(FAR struct mod_loadinfo_s *loadinfo,
722	                             bool is_vma)
723	{
724	  int ret;
725	
726	  binfo("loadinfo: %p\n", loadinfo);
727	  DEBUGASSERT(loadinfo && loadinfo->filfd >= 0);
728	
729	  /* Load section and program headers into memory */
730	
731	  ret = libelf_loadhdrs(loadinfo);
732	  if (ret < 0)
733	    {
734	      berr("ERROR: libelf_loadhdrs failed: %d\n", ret);
735	      goto errout_with_buffers;
736	    }
737	
738	#ifdef CONFIG_LIBC_ELF_GOT
739	  loadinfo->gotindex = libelf_findsection(loadinfo, ".got");
740	  if (loadinfo->gotindex >= 0)
741	    {
742	      binfo("GOT section found! index %d\n", loadinfo->gotindex);
743	      if (ioctl(loadinfo->filfd, FIOC_XIPBASE,
744	                (unsigned long)&loadinfo->xipbase) >= 0)
745	        {
746	          binfo("can use xipbase %zu\n", loadinfo->xipbase);
747	        }
748	    }
749	#endif
750	
751	  /* Determine total size to allocate */
752	
753	  libelf_elfsize(loadinfo, false);
754	
755	  ret = libelf_addrenv_alloc(loadinfo, loadinfo->textsize,
756	                             loadinfo->datasize);
757	  if (ret < 0)
758	    {
759	      berr("ERROR: Failed to create address environment: %d\n", ret);
760	      goto errout_with_buffers;
761	    }
762	
763	  /* If CONFIG_ARCH_ADDRENV=y, then the loaded ELF lies in a virtual address
764	   * space that may not be in place now.  elf_addrenv_select() will
765	   * temporarily instantiate that address space.
766	   */
767	
768	  ret = libelf_addrenv_select(loadinfo);
769	  if (ret < 0)
770	    {
771	      berr("ERROR: elf_addrenv_select() failed: %d\n", ret);
772	      goto errout_with_buffers;
773	    }
774	
775	  ret = libelf_loadfile(loadinfo, is_vma);
776	  if (ret < 0)
777	    {
778	      berr("ERROR: libelf_loadfile failed: %d\n", ret);
779	      goto errout_with_addrenv;
780	    }
781	
782	  /* Restore the original address environment */
783	
784	  ret = libelf_addrenv_restore(loadinfo);
785	  if (ret < 0)
786	    {
787	      berr("ERROR: libelf_addrenv_restore() failed: %d\n", ret);
788	      goto errout_with_buffers;
789	    }
790	
791	  return OK;
792	
793	errout_with_addrenv:
794	  libelf_addrenv_restore(loadinfo);
795	
796	errout_with_buffers:
797	  libelf_unload(loadinfo);
798	  return ret;
799	}
800	#endif
