84	/****************************************************************************
85	 * Name: libelf_symname
86	 *
87	 * Description:
88	 *   Get the symbol name in loadinfo->iobuffer[].
89	 *
90	 * Returned Value:
91	 *   0 (OK) is returned on success and a negated errno is returned on
92	 *   failure.
93	 *
94	 *   EINVAL - There is something inconsistent in the symbol table (should
95	 *            only happen if the file is corrupted).
96	 *   ESRCH - Symbol has no name
97	 *
98	 ****************************************************************************/
99	
100	static int libelf_symname(FAR struct mod_loadinfo_s *loadinfo,
101	                          FAR const Elf_Sym *sym, Elf_Off sh_offset)
102	{
103	  FAR uint8_t *buffer;
104	  off_t  offset;
105	  size_t readlen;
106	  size_t bytesread;
107	  int ret;
108	
109	  /* Get the file offset to the string that is the name of the symbol.  The
110	   * st_name member holds an offset into the file's symbol string table.
111	   */
112	
113	  if (sym->st_name == 0)
114	    {
115	      berr("ERROR: Symbol has no name\n");
116	      return -ESRCH;
117	    }
118	
119	  /* Allocate an I/O buffer.  This buffer is used by mod_symname() to
120	   * accumulate the variable length symbol name.
121	   */
122	
123	  ret = libelf_allocbuffer(loadinfo);
124	  if (ret < 0)
125	    {
126	      berr("ERROR: libelf_allocbuffer failed: %d\n", ret);
127	      return -ENOMEM;
128	    }
129	
130	  offset = sh_offset + sym->st_name;
131	
132	  /* Loop until we get the entire symbol name into memory */
133	
134	  bytesread = 0;
135	
136	  for (; ; )
137	    {
138	      /* Get the number of bytes to read */
139	
140	      readlen = loadinfo->buflen - bytesread;
141	      if (offset + readlen > loadinfo->filelen)
142	        {
143	          if (loadinfo->filelen <= offset)
144	            {
145	              berr("ERROR: At end of file\n");
146	              return -EINVAL;
147	            }
148	
149	          readlen = loadinfo->filelen - offset;
150	        }
151	
152	      /* Read that number of bytes into the array */
153	
154	      buffer = &loadinfo->iobuffer[bytesread];
155	      ret = libelf_read(loadinfo, buffer, readlen, offset);
156	      if (ret < 0)
157	        {
158	          berr("ERROR: libelf_read failed: %d\n", ret);
159	          return ret;
160	        }
161	
162	      bytesread += readlen;
163	
164	      /* Did we read the NUL terminator? */
165	
166	      if (memchr(buffer, '\0', readlen) != NULL)
167	        {
168	          /* Yes, the buffer contains a NUL terminator. */
169	
170	          return OK;
171	        }
172	
173	      /* No.. then we have to read more */
174	
175	      ret = libelf_reallocbuffer(loadinfo, CONFIG_LIBC_ELF_BUFFERINCR);
176	      if (ret < 0)
177	        {
178	          berr("ERROR: mod_reallocbuffer failed: %d\n", ret);
179	          return ret;
180	        }
181	
182	      offset += readlen;
183	    }
184	
185	  /* We will not get here */
186	
187	  return OK;
188	}
