190	/****************************************************************************
191	 * Name: libelf_symcallback
192	 *
193	 * Description:
194	 *   libelf_registry_foreach() callback function.  Test if the provided
195	 *   module, modp, exports the symbol of interest.  If so, return that symbol
196	 *   value and setup the module dependency relationship.
197	 *
198	 * Returned Value:
199	 *   0 (OK) is returned on success and a negated errno is returned on
200	 *   failure.
201	 *
202	 ****************************************************************************/
203	
204	static int libelf_symcallback(FAR struct module_s *modp, FAR void *arg)
205	{
206	  FAR struct mod_exportinfo_s *exportinfo = (FAR struct mod_exportinfo_s *)
207	                                            arg;
208	
209	  /* Check if this module exports a symbol of that name */
210	
211	  exportinfo->symbol = symtab_findbyname(modp->modinfo.exports,
212	                                         exportinfo->name,
213	                                         modp->modinfo.nexports);
214	
215	  if (exportinfo->symbol != NULL)
216	    {
217	      /* Yes.. save the dependency relationship and return SYM_FOUND to
218	       * stop the traversal.
219	       */
220	
221	#if CONFIG_LIBC_ELF_MAXDEPEND > 0
222	      int ret = libelf_depend(exportinfo->modp, modp);
223	      if (ret < 0)
224	        {
225	          berr("ERROR: libelf_depend failed: %d\n", ret);
226	          return ret;
227	        }
228	#endif
229	
230	      return SYM_FOUND;
231	    }
232	
233	  return SYM_NOT_FOUND;
234	}
