240	/****************************************************************************
241	 * Name: libelf_findsymtab
242	 *
243	 * Description:
244	 *   Find the symbol table section.
245	 *
246	 * Returned Value:
247	 *   0 (OK) is returned on success and a negated errno is returned on
248	 *   failure.
249	 *
250	 ****************************************************************************/
251	
252	int libelf_findsymtab(FAR struct mod_loadinfo_s *loadinfo)
253	{
254	  int i;
255	
256	  /* Find the symbol table section header and its associated string table */
257	
258	  for (i = 1; i < loadinfo->ehdr.e_shnum; i++)
259	    {
260	      if (loadinfo->shdr[i].sh_type == SHT_SYMTAB)
261	        {
262	          loadinfo->symtabidx = i;
263	          loadinfo->strtabidx = loadinfo->shdr[i].sh_link;
264	          break;
265	        }
266	    }
267	
268	  /* Verify that there is a symbol and string table */
269	
270	  if (loadinfo->symtabidx == 0)
271	    {
272	      berr("ERROR: No symbols in ELF file\n");
273	      return -EINVAL;
274	    }
275	
276	  return OK;
277	}
