279	/****************************************************************************
280	 * Name: libelf_readsym
281	 *
282	 * Description:
283	 *   Read the ELF symbol structure at the specified index into memory.
284	 *
285	 * Input Parameters:
286	 *   loadinfo - Load state information
287	 *   index    - Symbol table index
288	 *   sym      - Location to return the table entry
289	 *
290	 * Returned Value:
291	 *   0 (OK) is returned on success and a negated errno is returned on
292	 *   failure.
293	 *
294	 ****************************************************************************/
295	
296	int libelf_readsym(FAR struct mod_loadinfo_s *loadinfo, int index,
297	                   FAR Elf_Sym *sym, FAR Elf_Shdr *symtab)
298	{
299	  off_t offset;
300	
301	  /* Verify that the symbol table index lies within symbol table */
302	
303	  if (index < 0 || index > (symtab->sh_size / sizeof(Elf_Sym)))
304	    {
305	      berr("ERROR: Bad relocation symbol index: %d\n", index);
306	      return -EINVAL;
307	    }
308	
309	  /* Get the file offset to the symbol table entry */
310	
311	  offset = symtab->sh_offset + sizeof(Elf_Sym) * index;
312	
313	  /* And, finally, read the symbol table entry into memory */
314	
315	  return libelf_read(loadinfo, (FAR uint8_t *)sym, sizeof(Elf_Sym), offset);
316	}
