466	/****************************************************************************
467	 * Name: libelf_insertsymtab
468	 *
469	 * Description:
470	 *   Insert a symbol into the modules exportinfo array.
471	 *
472	 * Input Parameters:
473	 *   modp     - Module state information
474	 *   loadinfo - Load state information
475	 *   shdr     - Symbol table section header
476	 *   sym      - Symbol table entry
477	 *
478	 * Returned Value:
479	 *   0 (OK) is returned on success and a negated errno is returned on
480	 *   failure.
481	 *
482	 *   EINVAL - There is something inconsistent in the symbol table
483	 *            (should only happen if the file is corrupted).
484	 *
485	 ****************************************************************************/
486	
487	int libelf_insertsymtab(FAR struct module_s *modp,
488	                        struct mod_loadinfo_s *loadinfo,
489	                        FAR Elf_Shdr *shdr, FAR Elf_Sym *sym)
490	{
491	  FAR struct symtab_s *symbol;
492	  FAR Elf_Shdr *strtab = &loadinfo->shdr[shdr->sh_link];
493	  int ret = 0;
494	  int i;
495	  int j;
496	  int nsym;
497	  int symcount;
498	
499	  if (modp->modinfo.exports != NULL)
500	    {
501	      bwarn("Module export information already present - replacing");
502	      libelf_freesymtab((FAR void *)modp);
503	    }
504	
505	  /* Count the "live" symbols */
506	
507	  nsym = shdr->sh_size / sizeof(Elf_Sym);
508	  for (i = 0, symcount = 0; i < nsym; i++)
509	    {
510	      if (sym[i].st_name != 0 &&
511	          ELF_ST_BIND(sym[i].st_info) == STB_GLOBAL &&
512	          ELF_ST_TYPE(sym[i].st_info) != STT_NOTYPE &&
513	          ELF_ST_VISIBILITY(sym[i].st_other) == STV_DEFAULT)
514	        {
515	          symcount++;
516	        }
517	    }
518	
519	  if (symcount > 0)
520	    {
521	      modp->modinfo.exports = symbol =
522	                              loadinfo->exported =
523	                              lib_malloc(sizeof(*symbol) * symcount);
524	      if (modp->modinfo.exports)
525	        {
526	          /* Build out module's symbol table */
527	
528	          modp->modinfo.nexports = symcount;
529	          for (i = 0, j = 0; i < nsym; i++)
530	            {
531	              if (sym[i].st_name != 0 &&
532	                  ELF_ST_BIND(sym[i].st_info) == STB_GLOBAL &&
533	                  ELF_ST_TYPE(sym[i].st_info) != STT_NOTYPE &&
534	                  ELF_ST_VISIBILITY(sym[i].st_other) == STV_DEFAULT)
535	                {
536	                  ret = libelf_symname(loadinfo, &sym[i], strtab->sh_offset);
537	                  if (ret < 0)
538	                    {
539	                      lib_free((FAR void *)modp->modinfo.exports);
540	                      modp->modinfo.exports = NULL;
541	                      return ret;
542	                    }
543	
544	                  symbol[j].sym_name =
545	                      strdup((FAR char *)loadinfo->iobuffer);
546	                  symbol[j].sym_value =
547	                      (FAR const void *)(uintptr_t)sym[i].st_value;
548	                  j++;
549	                }
550	            }
551	
552	#ifdef CONFIG_SYMTAB_ORDEREDBYNAME
553	          symtab_sortbyname(symbol, symcount);
554	#endif
555	        }
556	      else
557	        {
558	          berr("Unable to get memory for exported symbols table");
559	          ret = -ENOMEM;
560	        }
561	    }
562	
563	  return ret;
564	}
