566	/****************************************************************************
567	 * Name: findep
568	 *
569	 * Description:
570	 *   Binary search comparison function
571	 *
572	 * Input Parameters:
573	 *   c1 - Comparand 1
574	 *   c2 - Comparand 2
575	 *
576	 ****************************************************************************/
577	
578	static int findep(FAR const void *c1, FAR const void *c2)
579	{
580	  FAR const struct eptable_s *m1 = (FAR const struct eptable_s *)c1;
581	  FAR const struct eptable_s *m2 = (FAR const struct eptable_s *)c2;
582	  return strcmp((FAR const char *)m1->epname, (FAR const char *)m2->epname);
583	}
