585	/****************************************************************************
586	 * Name: libelf_findglobal
587	 *
588	 * Description:
589	 *   Find a symbol in our library entry point table
590	 *
591	 * Input Parameters:
592	 *   modp     - Module state information
593	 *
594	 ****************************************************************************/
595	
596	void *libelf_findglobal(FAR struct module_s *modp,
597	                        FAR struct mod_loadinfo_s *loadinfo,
598	                        FAR Elf_Shdr *shdr, FAR Elf_Sym *sym)
599	{
600	  FAR Elf_Shdr *strtab = &loadinfo->shdr[shdr->sh_link];
601	  int ret;
602	  struct eptable_s key;
603	  FAR struct eptable_s *res;
604	
605	  ret = libelf_symname(loadinfo, sym, strtab->sh_offset);
606	  if (ret < 0)
607	    {
608	      return NULL;
609	    }
610	
611	  key.epname = loadinfo->iobuffer;
612	  res = bsearch(&key, global_table, nglobals,
613	                sizeof(struct eptable_s), findep);
614	  if (res != NULL)
615	    {
616	      return res->epaddr;
617	    }
618	  else
619	    {
620	      return NULL;
621	    }
622	}
