624	/****************************************************************************
625	 * Name: libelf_freesymtab
626	 *
627	 * Description:
628	 *   Free a symbol table
629	 *
630	 * Input Parameters:
631	 *   modp     - Module state information
632	 *
633	 ****************************************************************************/
634	
635	void libelf_freesymtab(FAR struct module_s *modp)
636	{
637	  FAR const struct symtab_s *symbol;
638	  int i;
639	
640	  if ((symbol = modp->modinfo.exports) != NULL)
641	    {
642	      for (i = 0; i < modp->modinfo.nexports; i++)
643	        {
644	          lib_free((FAR void *)symbol[i].sym_name);
645	        }
646	
647	      lib_free((FAR void *)symbol);
648	    }
649	}
