651	/****************************************************************************
652	 * Name: libelf_findsymbol
653	 *
654	 * Description:
655	 *   Locate a symbol in the ELF symbol table by its name.
656	 *
657	 * Input Parameters:
658	 *   loadinfo - Load state information containing the symbol table
659	 *   name     - The name of the symbol to search for
660	 *   sym      - Pointer to store the located symbol's table entry
661	 *
662	 * Returned Value:
663	 *   0 (OK) is returned on success and a negated errno is returned on
664	 *   failure.
665	 *
666	 ****************************************************************************/
667	
668	int libelf_findsymbol(FAR struct mod_loadinfo_s *loadinfo,
669	                      FAR const char *name, FAR Elf_Sym *sym)
670	{
671	  size_t num;
672	  int ret;
673	  int i;
674	
675	  if (loadinfo == NULL || name == NULL)
676	    {
677	      return -EINVAL;
678	    }
679	
680	  if (loadinfo->symtabidx == 0)
681	    {
682	      ret = libelf_findsymtab(loadinfo);
683	      if (ret < 0)
684	        {
685	          berr("ERROR: Failed to find symbol table\n");
686	          return ret;
687	        }
688	    }
689	
690	  /* Loop through all symbols in the symbol table */
691	
692	  num = loadinfo->shdr[loadinfo->symtabidx].sh_size / sizeof(Elf_Sym);
693	  for (i = 0; i < num; i++)
694	    {
695	      /* Read the symbol entry */
696	
697	      ret = libelf_readsym(loadinfo, i, sym,
698	                           &loadinfo->shdr[loadinfo->symtabidx]);
699	      if (ret)
700	        {
701	          berr("ERROR: Failed to read symbol entry\n");
702	          return ret;
703	        }
704	
705	      /* Get the symbol name */
706	
707	      ret = libelf_symname(loadinfo, sym,
708	                           loadinfo->shdr[loadinfo->strtabidx].sh_offset);
709	      if (ret < 0 && ret != -ESRCH)
710	        {
711	          berr("ERROR: Failed to get symbol name\n");
712	          return ret;
713	        }
714	
715	      /* Compare the symbol name with the given name */
716	
717	      if (strcmp((FAR const char *)loadinfo->iobuffer, name) == 0)
718	        {
719	          return ret;
720	        }
721	    }
722	
723	  return -ENOENT;
724	}
