157	#ifdef CONFIG_LIBC_ELF_DUMPBUFFER
158	void libelf_dumpentrypt(FAR struct mod_loadinfo_s *loadinfo)
159	{
160	  FAR const uint8_t *entry;
161	#ifdef CONFIG_ARCH_ADDRENV
162	  int ret;
163	
164	  /* If CONFIG_ARCH_ADDRENV=y, then the loaded ELF lies in a virtual address
165	   * space that may not be in place now.  libelf_addrenv_select() will
166	   * temporarily instantiate that address space.
167	   */
168	
169	  if (loadinfo->addrenv != NULL)
170	    {
171	      ret = libelf_addrenv_select(loadinfo);
172	      if (ret < 0)
173	        {
174	          berr("ERROR: libelf_addrenv_select() failed: %d\n", ret);
175	          return;
176	        }
177	    }
178	#endif
179	
180	  if (loadinfo->ehdr.e_type == ET_REL)
181	    {
182	      entry = (FAR const uint8_t *)
183	        ((uintptr_t)loadinfo->textalloc + loadinfo->ehdr.e_entry);
184	    }
185	  else if (loadinfo->ehdr.e_type == ET_EXEC)
186	    {
187	      entry = (FAR const uint8_t *)loadinfo->ehdr.e_entry;
188	    }
189	  else
190	    {
191	      entry = (FAR const uint8_t *)loadinfo->textalloc;
192	    }
193	
194	  libelf_dumpbuffer("Entry code", entry,
195	                    MIN(loadinfo->textsize - loadinfo->ehdr.e_entry, 512));
196	
197	#ifdef CONFIG_ARCH_ADDRENV
198	  /* Restore the original address environment */
199	
200	  if (loadinfo->addrenv != NULL)
201	    {
202	      ret = libelf_addrenv_restore(loadinfo);
203	      if (ret < 0)
204	        {
205	          berr("ERROR: libelf_addrenv_restore() failed: %d\n", ret);
206	        }
207	    }
208	#endif
209	}
