212	/****************************************************************************
213	 * Name: libelf_loadsymtab
214	 *
215	 * Description:
216	 *   Load the symbol table into memory.
217	 *
218	 ****************************************************************************/
219	
220	static int libelf_loadsymtab(FAR struct module_s *modp,
221	                             FAR struct mod_loadinfo_s *loadinfo)
222	{
223	  FAR Elf_Shdr *symhdr = &loadinfo->shdr[loadinfo->symtabidx];
224	  FAR Elf_Sym *sym = lib_malloc(symhdr->sh_size);
225	  int ret;
226	  int i;
227	
228	  if (sym == NULL)
229	    {
230	      return -ENOMEM;
231	    }
232	
233	  ret = libelf_read(loadinfo, (FAR uint8_t *)sym, symhdr->sh_size,
234	                    symhdr->sh_offset);
235	
236	  if (ret < 0)
237	    {
238	      berr("Failed to read symbol table\n");
239	      lib_free(sym);
240	      return ret;
241	    }
242	
243	  for (i = 0; i < symhdr->sh_size / sizeof(Elf_Sym); i++)
244	    {
245	      if (sym[i].st_shndx != SHN_UNDEF &&
246	          sym[i].st_shndx < loadinfo->ehdr.e_shnum)
247	        {
248	          FAR Elf_Shdr *s = &loadinfo->shdr[sym[i].st_shndx];
249	
250	          sym[i].st_value = sym[i].st_value + s->sh_addr;
251	        }
252	    }
253	
254	  ret = libelf_insertsymtab(modp, loadinfo, symhdr, sym);
255	  lib_free(sym);
256	  if (ret != 0)
257	    {
258	      binfo("Failed to export symbols program binary: %d\n", ret);
259	      return ret;
260	    }
261	
262	  return ret;
263	}
264	
265	/****************************************************************************
266	 * Name: libelf_insert
267	 *
268	 * Description:
269	 *   Verify that the file is an ELF module binary and, if so, load the
270	 *   module into kernel memory and initialize it for use.
271	 *
272	 *   NOTE: libelf_setsymtab() had to have been called in board-specific OS
273	 *   logic prior to calling this function from application logic (perhaps via
274	 *   boardctl(BOARDIOC_OS_SYMTAB).  Otherwise, insmod will be unable to
275	 *   resolve symbols in the OS module.
276	 *
277	 * Input Parameters:
278	 *
279	 *   filename - Full path to the module binary to be loaded
280	 *   modname  - The name that can be used to refer to the module after
281	 *     it has been loaded.
282	 *
283	 * Returned Value:
284	 *   A non-NULL module handle that can be used on subsequent calls to other
285	 *   module interfaces is returned on success.  If libelf_insert() was
286	 *   unable to load the module libelf_insert() will return a NULL handle
287	 *   and the errno variable will be set appropriately.
288	 *
289	 ****************************************************************************/
290	
291	FAR void *libelf_insert(FAR const char *filename, FAR const char *modname)
292	{
293	  FAR const struct symtab_s *exports;
294	  struct mod_loadinfo_s loadinfo;
295	  FAR struct module_s *modp;
296	  FAR void (**array)(void);
297	  int nexports;
298	  int ret;
299	  int i;
300	
301	  DEBUGASSERT(filename != NULL && modname != NULL);
302	  binfo("Loading file: %s\n", filename);
303	
304	  /* Get exclusive access to the module registry */
305	
306	  libelf_registry_lock();
307	
308	  /* Check if this module is already installed */
309	
310	#ifdef HAVE_LIBC_ELF_NAMES
311	  if (libelf_registry_find(modname) != NULL)
312	    {
313	      libelf_registry_unlock();
314	      set_errno(EEXIST);
315	      return NULL;
316	    }
317	#endif
318	
319	  /* Initialize the ELF library to load the program binary. */
320	
321	  ret = libelf_initialize(filename, &loadinfo);
322	  libelf_dumploadinfo(&loadinfo);
323	  if (ret != 0)
324	    {
325	      berr("ERROR: Failed to initialize to load module: %d\n", ret);
326	      goto errout_with_loadinfo;
327	    }
328	
329	  /* Allocate a module registry entry to hold the module data */
330	
331	  modp = lib_zalloc(sizeof(struct module_s));
332	  if (modp == NULL)
333	    {
334	      berr("Failed to allocate struct module_s\n");
335	      ret = -ENOMEM;
336	      goto errout_with_loadinfo;
337	    }
338	
339	#ifdef HAVE_LIBC_ELF_NAMES
340	  /* Save the module name in the registry entry */
341	
342	  strlcpy(modp->modname, modname, sizeof(modp->modname));
343	#endif
344	
345	  /* Load the program binary */
346	
347	  ret = libelf_load(&loadinfo);
348	  libelf_dumploadinfo(&loadinfo);
349	  if (ret != 0)
350	    {
351	      binfo("Failed to load ELF program binary: %d\n", ret);
352	      goto errout_with_registry_entry;
353	    }
354	
355	  /* Get the symbol table */
356	
357	  libelf_getsymtab(&exports, &nexports);
358	
359	  /* Bind the program to the kernel symbol table */
360	
361	  ret = libelf_bind(modp, &loadinfo, exports, nexports);
362	  if (ret != 0)
363	    {
364	      binfo("Failed to bind symbols program binary: %d\n", ret);
365	      goto errout_with_load;
366	    }
367	
368	  ret = libelf_loadsymtab(modp, &loadinfo);
369	  if (ret != 0)
370	    {
371	      binfo("Failed to load symbol table: %d\n", ret);
372	      goto errout_with_load;
373	    }
374	
375	  /* Save the load information */
376	
377	  modp->textalloc = (FAR void *)loadinfo.textalloc;
378	  modp->dataalloc = (FAR void *)loadinfo.datastart;
379	#ifdef CONFIG_ARCH_USE_SEPARATED_SECTION
380	  modp->sectalloc = (FAR void **)loadinfo.sectalloc;
381	  modp->nsect = loadinfo.ehdr.e_shnum;
382	#endif
383	
384	#if defined(CONFIG_FS_PROCFS) && !defined(CONFIG_FS_PROCFS_EXCLUDE_MODULE)
385	  modp->textsize  = loadinfo.textsize;
386	  modp->datasize  = loadinfo.datasize;
387	#endif
388	
389	  /* Call the module initializer */
390	
391	  switch (loadinfo.ehdr.e_type)
392	    {
393	      case ET_REL :
394	      case ET_DYN :
395	
396	          /* Process any preinit_array entries */
397	
398	          array = (FAR void (**)(void))loadinfo.preiarr;
399	          for (i = 0; i < loadinfo.nprei; i++)
400	            {
401	              array[i]();
402	            }
403	
404	          /* Process any init_array entries */
405	
406	          array = (FAR void (**)(void))loadinfo.initarr;
407	          for (i = 0; i < loadinfo.ninit; i++)
408	            {
409	              array[i]();
410	            }
411	
412	          modp->initarr = loadinfo.initarr;
413	          modp->ninit = loadinfo.ninit;
414	          modp->finiarr = loadinfo.finiarr;
415	          modp->nfini = loadinfo.nfini;
416	          break;
417	    }
418	
419	  /* Add the new module entry to the registry */
420	
421	  libelf_registry_add(modp);
422	
423	  libelf_uninitialize(&loadinfo);
424	  libelf_registry_unlock();
425	  return modp;
426	
427	errout_with_load:
428	  libelf_unload(&loadinfo);
429	#if CONFIG_LIBC_ELF_MAXDEPEND > 0
430	  libelf_undepend(modp);
431	#endif
432	errout_with_registry_entry:
433	  lib_free(modp);
434	errout_with_loadinfo:
435	  libelf_uninitialize(&loadinfo);
436	  libelf_registry_unlock();
437	  set_errno(-ret);
438	  return NULL;
439	}
