#ifdef CONFIG_LIBC_ELF_HAVE_SYMTAB
  /* Symbol table used by dlsym */

#  ifndef CONFIG_LIBC_ELF_SYMTAB_ARRAY
#    error "CONFIG_LIBC_ELF_SYMTAB_ARRAY must be defined"
#  endif

  /* Number of Symbols in the Table */

