input.new_string:
static int elf_loadbinary(FAR struct binary_s *binp,
                          FAR const char *filename,
                          FAR const struct symtab_s *exports,
                          int nexports)
{
  struct mod_loadinfo_s loadinfo;
  Elf_Sym sym;
  int ret;

  binfo("Loading file: %s\n", filename);

  /* Dump critical info about what we're trying to load */

  berr("ELF_LOAD: file=%s exports=%p nexports=%d\n",
       filename, exports, nexports);

  /* Initialize the ELF library to load the program binary. */

  ret = libelf_initialize(filename, &loadinfo);
  libelf_dumploadinfo(&loadinfo);
  if (ret != 0)
    {
      berr("ELF_LOAD: libelf_initialize failed: ret=%d errno=%d\n",
           ret, -ret);
      { volatile uint8_t *u = (volatile uint8_t *)0x04140000;
        const char *m = "ELF_INIT_FAIL\n";
        while(*m){while((*(volatile uint32_t*)(0x04140014)&0x20)==0);*u=*m++;} }
      goto errout_with_init;
    }

  /* Log ELF identity: type, machine, entry point */

  { volatile uint8_t *u = (volatile uint8_t *)0x04140000;
    const char *msgs[] = {
      "ELF_TYPE=", NULL, " MACH=", NULL, " ENTRY=", NULL, "\n", NULL
    };
    char buf[32];
    int n;
    n = 0; while (n < 32) buf[n++] = 0;
    n = 0; { unsigned int v = loadinfo.ehdr.e_type; if (v == 0) buf[n++] = '0';
      else { char t[16]; int i = 0; while (v) { t[i++] = '0' + (v % 10); v /= 10; }
      while (i) buf[n++] = t[--i]; } } buf[n] = 0; msgs[1] = buf;
    n = 0; { unsigned int v = loadinfo.ehdr.e_machine; char b2[16];
      if (v == 0) b2[n++] = '0'; else { char t[16]; int i = 0;
      while (v) { t[i++] = '0' + (v % 10); v /= 10; }
      while (i) b2[n++] = t[--i]; } } b2[n] = 0; msgs[3] = b2;
    n = 0; { unsigned long v = (unsigned long)loadinfo.ehdr.e_entry;
      if (v == 0) buf[0] = '0'; else { int i = 0;
      while (v) { buf[i++] = "0123456789abcdef"[v & 15]; v >>= 4; }
      buf[i] = 0; int j = 0, k = i - 1; while (j < k)
      { char t = buf[j]; buf[j] = buf[k]; buf[k] = t; j++; k--; } } }
      msgs[5] = buf;
    for (int i = 0; i < 7; i++) if (msgs[i])
      { const char *p = msgs[i]; while (*p) {
        while ((*(volatile uint32_t *)(0x04140014) & 0x20) == 0); *u = *p++; } }
  }

