/****************************************************************************
 * Name: elf_uart_puts / elf_uart_puthex / elf_uart_putdec
 *
 * Description:
 *   Low-level UART debug helpers for this board (UART0 base 0x04140000).
 *   Used when serial driver is not yet available during ELF loading.
 *
 ****************************************************************************/

static void elf_uart_putc(char c)
{
  volatile uint8_t *u = (volatile uint8_t *)0x04140000;
  while ((*(volatile uint32_t *)(0x04140014) & 0x20) == 0);
  *u = c;
}

static void elf_uart_puts(FAR const char *s)
{
  while (*s) elf_uart_putc(*s++);
}

static void elf_uart_puthex(unsigned long v)
{
  int i;
  elf_uart_puts("0x");
  for (i = (sizeof(v) * 2) - 1; i >= 0; i--)
    elf_uart_putc("0123456789abcdef"[(v >> (i * 4)) & 0xf]);
}

static void elf_uart_putdec(int v)
{
  char buf[12];
  int i = 0, neg = 0;
  if (v < 0) { neg = 1; v = -v; }
  if (v == 0) buf[i++] = '0';
  else { while (v) { buf[i++] = '0' + (v % 10); v /= 10; } }
  if (neg) buf[i++] = '-';
  while (i) elf_uart_putc(buf[--i]);
}

